{
  "core_question": "How should a US-based clinical-stage biotech structure and value a co-development/co-commercialization agreement with an EU pharma for its Phase 3 oncology asset under accelerated approval, balancing clinical, regulatory, IP, territorial, and financial risks?",
  "rationale": "The deal requires clinical insight on program risk and regulatory pathways (healthcare), jurisdictional and IP exposure analysis across US/EU/UK territories (legal), and detailed valuation including rNPV, milestone calibration, and royalty structuring (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "Given a Phase 3 oncology program in the US with potential accelerated approval, what are the key clinical‑program risks that should be quantified for valuation purposes, and how do these risks influence milestone payment design?",
    "legal": "What contractual provisions are essential to allocate territorial rights (US to the biotech, EU/UK to the pharma), manage IP ownership and licensing across jurisdictions, and address regulatory compliance under FDA accelerated approval and post‑Brexit EU/UK frameworks?",
    "finance": "How should we calculate an rNPV for this asset, calibrate milestone payments and tiered royalty rates, and structure the overall deal economics (upfront, milestones, royalties) to reflect shared risk while ensuring fair value for both parties?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Potentially stale FDA accelerated‑approval guidance post‑2024, EU/UK regulatory changes after Brexit, recent IP law amendments in the US and EU, and current market conditions affecting rNPV assumptions."
}
